module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  localparam ADDR_WIDTH = $clog2(DEPTH);
  localparam PTR_WIDTH  = ADDR_WIDTH + 1;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [PTR_WIDTH-1:0] wr_ptr;
  reg [PTR_WIDTH-1:0] rd_ptr;

  wire wr_valid = wr_en & ~full;
  wire rd_valid = rd_en & ~empty;

  assign full  = (wr_ptr[PTR_WIDTH-1:1] == rd_ptr[PTR_WIDTH-1:1]) &&
                 (wr_ptr[0] != rd_ptr[0]);
  assign empty = (wr_ptr == rd_ptr);

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr <= {PTR_WIDTH{1'b0}};
      rd_ptr <= {PTR_WIDTH{1'b0}};
      dout   <= {WIDTH{1'b0}};
    end else begin
      if (wr_valid) begin
        mem[wr_ptr[ADDR_WIDTH-1:0]] <= din;
        wr_ptr <= wr_ptr + 1'b1;
      end
      if (rd_valid) begin
        dout   <= mem[rd_ptr[ADDR_WIDTH-1:0]];
        rd_ptr <= rd_ptr + 1'b1;
      end
    end
  end

endmodule
