double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    // Layout:
    // W1: n_hidden * n_in, row-major: W1[j][k] = params[j*n_in + k]
    // b1: n_hidden
    // W2: n_hidden
    // b2: 1

    int w1_offset = 0;
    int b1_offset = w1_offset + n_hidden * n_in;
    int w2_offset = b1_offset + n_hidden;
    int b2_offset = w2_offset + n_hidden;

    // Zero out gradients
    int total_params = b2_offset + 1;
    for (int i = 0; i < total_params; ++i) {
        grad[i] = 0.0;
    }

    double total_loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;

        // Compute hidden layer
        double h[n_hidden];
        for (int j = 0; j < n_hidden; ++j) {
            double sum = 0.0;
            for (int k = 0; k < n_in; ++k) {
                sum += params[w1_offset + j * n_in + k] * x[k];
            }
            sum += params[b1_offset + j];
            h[j] = tanh(sum);
        }

        // Compute z
        double z = 0.0;
        for (int j = 0; j < n_hidden; ++j) {
            z += params[w2_offset + j] * h[j];
        }
        z += params[b2_offset];

        // Compute p = sigmoid(z)
        double p = 1.0 / (1.0 + exp(-z));

        // Clamp p to avoid log(0)
        double p_clamped = p;
        if (p_clamped < 1e-15) p_clamped = 1e-15;
        if (p_clamped > 1.0 - 1e-15) p_clamped = 1.0 - 1e-15;

        double y_s = y[s];
        double loss_s = -(y_s * log(p_clamped) + (1.0 - y_s) * log(1.0 - p_clamped));
        total_loss += loss_s;

        // Gradient of loss w.r.t. z: dL/dz = p - y
        double dz = p - y_s;

        // Gradient w.r.t. W2[j] and b2
        for (int j = 0; j < n_hidden; ++j) {
            grad[w2_offset + j] += dz * h[j];
        }
        grad[b2_offset] += dz;

        // Gradient w.r.t. h[j]: dh_j = dz * W2[j]
        // Gradient w.r.t. pre-activation a_j: da_j = dh_j * (1 - h_j^2)
        // Gradient w.r.t. W1[j][k] and b1[j]
        for (int j = 0; j < n_hidden; ++j) {
            double dh_j = dz * params[w2_offset + j];
            double da_j = dh_j * (1.0 - h[j] * h[j]);
            for (int k = 0; k < n_in; ++k) {
                grad[w1_offset + j * n_in + k] += da_j * x[k];
            }
            grad[b1_offset + j] += da_j;
        }
    }

    // Average loss and scale gradients
    double avg_loss = total_loss / n_samples;
    for (int i = 0; i < total_params; ++i) {
        grad[i] /= n_samples;
    }

    return avg_loss;
}
